L40_1 = "하지만 인과를 연산하는 테라브레인의 집합체. 하이브 컨트롤."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "でも因果を演算するテラブレインの集合体、ハイブコントロールが。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "But the Terrabrain cluster that does causality calculation, Hive Control."
L39_1.m_Talk_ENG = L40_1
L40_1 = "但是，運算因果的特拉大腦集合體……巢穴控制系統。"
