L40_1.m_Pos = "C"
L41_1 = "그 하이브 컨트롤이 널 선택했다는 건 미래에 중요한 분기점 역할을 하게 된다는 뜻이야."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "あのハイブコントロールがあなたを選んだということは、あなたは未来の重要な分岐点として役割を担うということよ。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Having Hive Control choose you means that you'll serve as an important turning point in the future."
L40_1.m_Talk_ENG = L41_1
L41_1 = "是巢穴控制系統選擇了你，就表示你將成為未來的一個重要轉捩點。"
