L42_1 = "그게 관리국이 널 차기 전대장으로 추천한 이유, 우리가 그 화재에서 널 구한 이유……."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "それが管理局があなたを次の戦隊長として推奨した理由。私たちがあなたをあの日助けた理由よ。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "That's the reason why the Administration recommended you as the next Commander, and why we saved you in that fire..."
L41_1.m_Talk_ENG = L42_1
L42_1 = "這就是為什麼管理局推薦你擔任下一任戰隊長，也是為什麼我們從那場大火中救了你……"
L41_1.m_Talk_TWN = L42_1
L42_1 = "这就是为什么管理局推荐你担任下一任战队长，也是为什么我们从那场大火中救了你……"
