L27_1.m_CharStrID = L28_1
L28_1 = "다른 아이들이 뛰놀며 학교에 다닐 때, 인생의 대부분을 병원에서 보냈죠."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "同年代の子どもたちが学校に通い、自由に走り回っている間……あの子は人生の大半を病院で過ごしました。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "While kids her age were running around and going to school, she spent most of her days at the hospital."
L27_1.m_Talk_ENG = L28_1
L28_1 = "當其他孩子活蹦亂跳能夠去上學的時候，她大部分時間都在醫院裡度過。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "当其他孩子活蹦乱跳能够去上学的时候，她大部分时间都在医院里度过。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "While kids her age were running around and going to school, she spent most of her days at the hospital."
L27_1.m_Talk_DEU = L28_1
L28_1 = "While kids her age were running around and going to school, she spent most of her days at the hospital."
