L29_1 = "I'm ashamed to admit this as a parent, but... I was getting ready to say goodbye to her."
L28_1.m_Talk_DEU = L29_1
L29_1 = "I'm ashamed to admit this as a parent, but... I was getting ready to say goodbye to her."
