L5_1.m_CharStrID = L6_1
L6_1 = "그 아이, 아프기 전에는 소방관님처럼 남을 돕는 게 꿈이었어요."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "あの子、病気になる前は消防士さんみたいに人を助ける仕事に就くのが夢だったんです。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Before my daughter got sick, she also dreamt of helping others like you."
L5_1.m_Talk_ENG = L6_1
L6_1 = "在生病之前，她的夢想是像消防員一樣幫助別人。"
