L44_1 = "화재 현장에서 구조자를 구하는데 수단이나 방법 같은 건 가리지 않아."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "火災現場で人を助ける時は手段を選ばない。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "I don't mind using any means necessary to rescue people in a fire."
L43_1.m_Talk_ENG = L44_1
L44_1 = "我會不惜一切手段和代價，拯救火災現場的求救者。"
L43_1.m_Talk_TWN = L44_1
