L45_1 = "관리국의 정보와 힘이 있다면…… 지금까지는 구할 수 없었던 사람도 구할 수 있겠지."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "管理局の情報と力をもってすれば……今までは救えなかった人も救えるだろう。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "And if I have the Administration's intel and power... I'll be able to save others whom I couldn't save before."
L44_1.m_Talk_ENG = L45_1
L45_1 = "如果能借助管理局的資訊和力量……我們一定能夠拯救更多迄今為止無法拯救的人。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "如果能借助管理局的信息和力量……我们一定能够拯救更多迄今为止无法拯救的人。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "And if I have the Administration's intel and power... I'll be able to save others whom I couldn't save before."
