L1_1.m_CharScale = L2_1
L1_1.m_CharScaleTime = 0.01
L2_1 = "<color=#ffd34c>현실의 싸움이라는 건, 단순한 전투력 수치로 결정되는 게 아니다. </color>"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "<color=#ffd34c>現実の戦いというものは、単に戦闘力の数値で決まるものではない。</color>"
L1_1.m_Talk_JPN = L2_1
L2_1 = "<color=#ffd34c>But reality isn't all about numbers and categories.</color>"
L1_1.m_Talk_ENG = L2_1
L2_1 = "<color=#ffd34c>戰鬥的勝負並非僅僅取決於戰鬥力數值的高低。</color>"
L1_1.m_Talk_TWN = L2_1
L2_1 = "<color=#ffd34c>战斗的胜负并非仅仅取决于战斗力数值的高低。</color>"
L1_1.m_Talk_SCN = L2_1
L2_1 = "<color=#ffd34c>But reality isn't all about numbers and categories.</color>"
L1_1.m_Talk_DEU = L2_1
L2_1 = "<color=#ffd34c>But reality isn't all about numbers and categories.</color>"
L1_1.m_Talk_FRA = L2_1
L2_1 = {}
L3_1 = "YAKSHA_ACT2_INTERUDE6@252#Talk"
