L3_1[2] = L5_1
L2_1.m_CharScale = L3_1
L2_1.m_CharScaleTime = 0.01
L3_1 = "<color=#ffd34c>강하다고 해서 반드시 이기는 것도 아니고, 약하다고 해서 반드시 지는 것도 아니다.</color>"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "<color=#ffd34c>強いからと言って勝つわけでも、弱いからと言って負けるわけでもない。</color>"
L2_1.m_Talk_JPN = L3_1
L3_1 = "<color=#ffd34c>Being strong doesn't necessarily mean you win, and being weak doesn't necessarily mean you lose.</color>"
L2_1.m_Talk_ENG = L3_1
L3_1 = "<color=#ffd34c>強不代表著會贏，弱也不代表著會輸。</color>"
L2_1.m_Talk_TWN = L3_1
L3_1 = "<color=#ffd34c>强不代表着会赢，弱也不代表着会输。</color>"
L2_1.m_Talk_SCN = L3_1
