L8_1 = "전 스승님의 가르침대로, 항상 한계의 한계를 넘어왔으니까요!"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "私は師匠の教え通り、いつも限界の限界を越えてきましたから！"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Because I've always been going beyond my limits, just like you taught me!"
L7_1.m_Talk_ENG = L8_1
L8_1 = "我一直按照師父所教的那樣，不斷挑戰著自己的極限！"
L7_1.m_Talk_TWN = L8_1
L8_1 = "我一直按照老师所教的那样，不断挑战着自己的极限！"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Because I've always been going beyond my limits, just like you taught me!"
L7_1.m_Talk_DEU = L8_1
