L11_1 = "관리국에 계속 있을 생각이라면, 저 녀석의 뒷모습을 마음 속에 새겨둬라."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "管理局に居続けるつもりなら、あいつの背中を忘れるな。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "if you're thinking of staying in the Administration, take the image of her back to the heart."
L10_1.m_Talk_ENG = L11_1
L11_1 = "但如果你打算繼續留在管理局，就好好記住那傢伙的背影吧。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "但如果你打算继续留在管理局，就好好记住那家伙的背影吧。"
L10_1.m_Talk_SCN = L11_1
L11_1 = "if you're thinking of staying in the Administration, take the image of her back to the heart."
L10_1.m_Talk_DEU = L11_1
L11_1 = "if you're thinking of staying in the Administration, take the image of her back to the heart."
