L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L12_1 = "저 모습은 언젠가 네가 다다라야 할 모습이고, 또 누군가에게 보여주게 될 모습이니까."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "あれはいつかお前が辿り着かねばならない境地であり、また誰かに見せてやらねばならない姿なのだから。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "That is what you'll have to become and show to others one day."
L11_1.m_Talk_ENG = L12_1
L12_1 = "那將會是你總有一天會達到的樣子，也是別人會看到你的樣子。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "那将会是你总有一天会达到的样子，也是别人会看到你的样子。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "That is what you'll have to become and show to others one day."
L11_1.m_Talk_DEU = L12_1
L12_1 = "That is what you'll have to become and show to others one day."
