L13_1.m_CharStrID = "RABBIT_YAKSHA_NULL_NULL"
L13_1.m_Pos = "C"
L14_1 = "예를 들면, 너도 마찬가지야. 앨리스 브레이드우드."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "たとえば、あなたもそうよ。アリス・ブレイドウッド。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "For instance, like you, Alice Braidwood."
L13_1.m_Talk_ENG = L14_1
L14_1 = "比如說你也是。艾莉絲·布雷德伍德。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "比如说你也是。艾力斯·布雷德伍德。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "For instance, like you, Alice Braidwood."
L13_1.m_Talk_DEU = L14_1
