L15_1 = "YAKSHA_ACT2_INTERUDE6@264#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 264
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 6400214
