L14_1.m_CharStrID = "RABBIT_YAKSHA_NULL_NULL"
L14_1.m_Pos = "C"
L15_1 = "어렸을 때 화재를 겪은 뒤, 줄곧 소방관을 꿈 꿔왔지?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "子どもの頃火災を経験して、消防士になる夢を持つようになったんでしょう？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "After that fire incident you had when you were little, you've always dreamt of being a firefighter, right?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "你小時候因為經歷了火災，就一直夢想成為一名消防員吧？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "你小时候因为经历了火灾，就一直梦想成为一名消防员吧？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "After that fire incident you had when you were little, you've always dreamt of being a firefighter, right?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "After that fire incident you had when you were little, you've always dreamt of being a firefighter, right?"
L14_1.m_Talk_FRA = L15_1
