L16_1 = "YAKSHA_ACT2_INTERUDE6@265#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 265
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 6400214
L15_1.m_CutScenStrID = "YAKSHA_ACT2_INTERUDE6"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "RABBIT_YAKSHA_NULL_NULL"
L15_1.m_Pos = "C"
L16_1 = "그리고 그 꿈을 이루기 위해, 지금껏 꾸준히 노력해서 결국 소방관이 되었잖아?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "その夢を叶えるために努力し続けた結果、消防士になれたのよね。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "And you worked hard to achieve that dream, eventually becoming one, didn't you?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "為了實現這個夢想，你非常努力，最終得願以償，對嗎？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "为了实现这个梦想，你非常努力，最终得愿以偿，对吗？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "And you worked hard to achieve that dream, eventually becoming one, didn't you?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "And you worked hard to achieve that dream, eventually becoming one, didn't you?"
L15_1.m_Talk_FRA = L16_1
