L16_1.m_Face = L17_1
L16_1.m_CharStrID = "RABBIT_YAKSHA_NULL_NULL"
L16_1.m_Pos = "C"
L17_1 = "다시 말해, 조금씩 CRF를 소모한 결과로써 외부의 현실을 개변했다고 할 수 있지."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "だから、少しずつCRFを消耗したことで外部の現実を改変させたってことになるね。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "In other words, as a result of consuming CRF in tiny portions, your external reality had changed."
L16_1.m_Talk_ENG = L17_1
L17_1 = "換句話說，這就是一點一點消耗CRF而改變外部現實的結果。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "换句话说，这就是一点一点消耗CRF而改变外部现实的结果。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "In other words, as a result of consuming CRF in tiny portions, your external reality had changed."
L16_1.m_Talk_DEU = L17_1
L17_1 = "In other words, as a result of consuming CRF in tiny portions, your external reality had changed."
