L19_1.m_CutScenStrID = "YAKSHA_ACT2_INTERUDE6"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "내가 개변하고 싶은 건, 외부의 현실 같은 거창한 게 아니야."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "m_bTalkCenterFadeIn"
L19_1[L20_1] = true
L20_1 = "外部の現実だの何だの、アタシが改変したいのはそんな大それたものじゃない。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "The thing I want to change isn't anything grand like changing the world."
L19_1.m_Talk_ENG = L20_1
L20_1 = "改變世界什麼的，對我來說太過宏大，太過遙遠了。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "改变世界什么的，离我太过宏大，太过遥远了。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "The thing I want to change isn't anything grand like changing the world."
L19_1.m_Talk_DEU = L20_1
L20_1 = "The thing I want to change isn't anything grand like changing the world."
L19_1.m_Talk_FRA = L20_1
